9| * @description Transitions one `interrupted` task back to runnable
10| *   (`in_stage`) exactly the way manual `resumeTask` does — cleared
11| *   `wasInterrupted`, fresh auto-iteration budget, history entry, persisted
12| *   markdown — but WITHOUT dispatching execution itself. Additionally stamps
13| *   the durable `resumedAfterInterruption` marker (plus an `interruptedAt`
14| *   snapshot of the pre-flip timestamp, so oldest-interruption ordering
15| *   survives the flip) that keeps Rule 0 priority until the first dispatch
16| *   consumes it. The caller is either startup recovery (the normal
17| *   `scheduleTick` then dispatches under the busy gate) or `scheduleTick`
18| *   (which dispatches immediately after). Never calls `executeStage`
19| *   directly, so the single-active invariant holds. Idempotent: a
20| *   non-interrupted task is returned untouched.
21| * @param {Object} store
22| * @param {string} projectId
23| * @param {string} taskId
24| * @param {string} [projectCwd]
25| * @returns {Object|null} The task, or null when unknown.
26|  * @example autoResumeTask(store, "p1", "t1") => task (status "in_stage")
27| ***/
28|export function autoResumeTask(store, projectId, taskId, projectCwd, { reason } = {}) {
29|	const task = store.getTask(projectId, taskId);
30|	if (!task || task.status !== "interrupted") return task || null;
31|	// Snapshot BEFORE the flip: `updatedAt` is about to become "now" for
32|	// every resumed task, which would destroy oldest-first ordering.
33|	task.interruptedAt =
34|		task.updatedAt || task.enteredStageAt || new Date().toISOString();
35|	task.resumedAfterInterruption = true;
36|	task.wasInterrupted = false;
37|	task.status = "in_stage";
38|	task.updatedAt = new Date().toISOString();
39|	if (typeof store._resetAutoIteration === "function") {
40|		store._resetAutoIteration(task);
41|	}
42|	const historyAction =
43|		"Auto-resumed after server restart — prioritised in queue";
44|	if (typeof store._recordHistory === "function") {
45|		try {
46|			store._recordHistory(task, historyAction, task.updatedAt);
47|		} catch {
48|			// History is best-effort; the flip already happened.
49|		}
50|	}
51|	// WP6 auto-resume evidence: every resume records WHAT was discovered
52|	// (markers present, SHAs, verdict) into the timeline so an operator can
53|	// audit the decision. Best-effort: evidence gathering must never break
54|	// the flip.
55|	try {
56|		const evidence = collectResumeEvidence(store, task);
57|		let stageLabel = task.currentStageId || "stage";
58|		try {
59|			const project =
60|				typeof store.projectStore?.getProject === "function"
61|					? store.projectStore.getProject(projectId)
62|					: null;
63|			if (project) {
64|				const stages = resolveStagesForTask(project, task);
65|				const stage = resolveCandidateStage(stages, task.currentStageId);
66|				if (stage?.name || stage?.id) stageLabel = stage.name || stage.id;
67|			}
68|		} catch {
69|			// Label resolution is best-effort; the evidence still records.
70|		}
71|		if (typeof store._recordTimeline === "function") {
72|			store._recordTimeline(task, {
73|				stage: stageLabel,
74|				status: "Resumed",
75|				reason: reason || historyAction,
76|				...evidence,
77|			});
78|		}
79|	} catch {
80|		// Timeline evidence is best-effort; the flip already happened.
81|	}
82|	const cwd =
83|		typeof store._resolveProjectCwd === "function"
84|			? store._resolveProjectCwd(projectId, projectCwd)
85|			: projectCwd;
86|	if (typeof store._saveTaskMarkdown === "function") {
87|		store._saveTaskMarkdown(cwd, task);
88|	}
89|	store.eventBridge?.broadcastGlobal?.("TASK_UPDATED", task);
90|	return task;
91|}

