1|import { normalizeStageType } from '../stageTypes.js';
2|import { isRejectedTask } from './failureReason';
3|import { isRetryInProgress, isTaskSettledStatus } from './taskRetryState';
4|
5|/***
6| * MARK: isTaskCompleted
7| * @description Single source of truth for the task completion status vocabulary.
8| * A task counts as completed when its status is 'completed' or the legacy alias 'done'.
9| * Use this instead of inline status checks so the whole UI stays in sync if the
10| * status vocabulary ever changes (see stageAnalytics and collapsed rail badges).
11| * @example isTaskCompleted({ status: 'completed' }) => true
12| * @example isTaskCompleted({ status: 'in_stage' }) => false
13| * @example isTaskCompleted(null) => false
14| * @param {Object} [task] - The task object (or null/undefined for safety).
15| * @returns {boolean} True when the task is completed.
16| ***/
17|export function isTaskCompleted(task) {
18|  return task?.status === 'completed' || task?.status === 'done';
19|}
20|
21|/***
22| * MARK: isWaitingForPickupTask
23| * @description Status-level fallback for "this task is waiting for a
24| * runner/scheduler to pick it up right now". Used only when the engine
25| * snapshot carries no authoritative `openQueueDepth` (offline snapshots,
26| * tests) — see `resolveUniversalNowPlaying`. Mirrors the backend
27| * `isWaitingForPickup` contract as far as the loaded list allows:
28| * terminal, waiting-human, paused, advancing, checkpoint, idle, and
29| * running_* tasks never wait; blocked tasks never wait; and interrupted
30| * tasks never wait here because auto-resumability needs backend stage
31| * resolution the list cannot reproduce. Fails open for anything else: an
32| * unknown status reads as waiting rather than hiding queued work.
33| * @example isWaitingForPickupTask({ status: 'in_stage' }) => true
34| * @example isWaitingForPickupTask({ status: 'failed' }) => false
35| * @example isWaitingForPickupTask({ status: 'in_stage', blockedBy: ['a'] }) => false
36| * @example isWaitingForPickupTask(null) => false
37| * @param {Object} [task] - The task object (or null/undefined for safety).
38| * @returns {boolean} True when the task reads as waiting for pickup.
39| ***/
40|export function isWaitingForPickupTask(task) {
41|  if (task == null || typeof task !== 'object') return false;
42|  const status = typeof task.status === 'string' ? task.status : '';
43|  if (
44|    status === 'completed' ||
45|    status === 'done' ||
46|    status === 'failed' ||
47|    status === 'cancelled' ||
48|    status === 'waiting_human' ||
49|    status === 'paused' ||
50|    status === 'advancing' ||
51|    status === 'checkpoint' ||
52|    status === 'idle' ||
53|    status === 'running' ||
54|    status.startsWith('running_') ||
55|    status === 'interrupted'
56|  ) {
57|    return false;
58|  }
59|  // The scheduler's own verdict wins when the payload carries it; otherwise
60|  // any declared prerequisite reads as blocking (conservative: the list
61|  // cannot tell a freed blocker from a live one).
62|  if (task.isBlocked === true) return false;
63|  if (Array.isArray(task.blockedBy) && task.blockedBy.length > 0) return false;
64|  return true;
65|}
66|
67|/***
68| * MARK: isAutoIterationInProgress
69| * @description True when a task is in an automatic CROSS-STAGE re-run: the
70| *   failback moved it to a different stage and the engine re-queued it there.
71| *   Such a task is normal in-progress work in the new stage — it must not be
72| *   labelled RETRYING (that is `isRetryInProgress` in ./taskRetryState.js,
73| *   same stage only) and must not be labelled FAILED either (the stored
74| *   failureReason is deliberately kept for the next attempt's prompt). New
75| *   backend records flag this explicitly with `autoIterating`; payloads from
76| *   an older backend only carry `autoRetrying`, so a moved task (current
77| *   stage differs from the failed stage) is detected through
78| *   `isRetryInProgress` being false.
79| * @example isAutoIterationInProgress({ autoRetrying: true, autoIterating: true, currentStageId: '1', lastError: { stageId: '2' } }) => true
80| * @example isAutoIterationInProgress({ autoRetrying: true, currentStageId: '1', lastError: { stageId: '2' } }) => true
81| * @example isAutoIterationInProgress({ autoRetrying: true, currentStageId: '2', lastError: { stageId: '2' } }) => false
82| * @example isAutoIterationInProgress({ autoRetrying: false, autoIterating: true }) => true
83| * @param {Object} [task] - The task object (or null/undefined for safety).
84| * @returns {boolean} True when a cross-stage automatic re-run is in progress.
85| ***/
86|export function isAutoIterationInProgress(task) {
87|  // Settled tasks are never iterating; the settled-status vocabulary lives in
88|  // exactly one place (isTaskSettledStatus) so this read and the RETRYING
89|  // read can never disagree about whether the task is still live.
90|  if (isTaskSettledStatus(task)) return false;
91|  if (task?.autoIterating === true) return true;
92|  return task?.autoRetrying === true && !isRetryInProgress(task);
93|}
94|
95|/***
96| * MARK: isTaskFailed
97| * @description Single source of truth for whether a task reads as FAILED in
98| *   the UI (card, inspector, full page, retrospective). An explicit `failed`
99| *   status always reads as failed. Otherwise the stored `failureReason` only
100| *   reads as failed when no automatic re-run is about to clear it: a
101| *   same-stage in-place retry (`isRetryInProgress`) or a cross-stage
102| *   continuation (`isAutoIterationInProgress`) keeps the label honest while
103| *   the engine recovers on its own. A deliberate rejection is the exception:
104| *   it keeps its FAILED/REJECTED banner even while its retry is queued,
105| *   because the rejection reason is about to be snapshotted into the next
106| *   attempt and hiding it would hide pending context. Fails safe on
107| *   missing input: null, undefined, and reason-less tasks never read failed.
108| * @example isTaskFailed({ status: 'failed' }) => true
109| * @example isTaskFailed({ status: 'in_stage', failureReason: 'boom', autoRetrying: true, currentStageId: '2', lastError: { stageId: '2' } }) => false
