24| * @param {string} [projectCwd]
25| * @returns {Object|null} The task, or null when unknown.
26|  * @example autoResumeTask(store, "p1", "t1") => task (status "in_stage")
27| ***/
28|export function autoResumeTask(store, projectId, taskId, projectCwd, { reason } = {}) {
29|	const task = store.getTask(projectId, taskId);
30|	if (!task || task.status !== "interrupted") return task || null;
31|	// Snapshot BEFORE the flip: `updatedAt` is about to become "now" for
32|	// every resumed task, which would destroy oldest-first ordering.
33|	task.interruptedAt =
34|		task.updatedAt || task.enteredStageAt || new Date().toISOString();
35|	task.resumedAfterInterruption = true;
36|	task.wasInterrupted = false;
37|	task.status = "in_stage";
