1|/***
2| * MARK: collectResumeEvidence
3| * @description Gathers the auto-resume evidence bundle for a task: which
4| *   generic rehydration markers were present, the relevant SHAs, and the
5| *   resume verdict. Deploy-specific evidence (attempt ids, last-result age)
6| *   is continuity-owned and recorded by the implementation plugin, not here.
7| *   Total: every read is guarded so evidence gathering never throws.
8| * @param {Object} store
9| * @param {Object} task
10| * @param {string} [verdict] - Resume verdict reason (defaults to "auto-resumed").
11| * @returns {{ markers: Array<string>, shas: Object, verdict: string }}
12|  * @example collectResumeEvidence(store, task) => { markers, shas, verdict: "auto-resumed" }
13| ***/
14|export function collectResumeEvidence(store, task, verdict = "auto-resumed") {
15|	void store;
16|	const markers = [];
17|	const shas = {};
18|	try {
19|		if (typeof task?.preMergeMainSha === "string" && task.preMergeMainSha.trim()) {
20|			markers.push("preMergeMainSha");
21|			shas.preMergeMainSha = task.preMergeMainSha;
22|		}
23|		const baseline = task?.reviewBaseline;
24|		if (
25|			baseline &&
26|			typeof baseline === "object" &&
27|			!Array.isArray(baseline) &&
28|			typeof baseline.mergedAt === "string" &&
29|			baseline.mergedAt.trim()
30|		) {
31|			markers.push("reviewBaseline.mergedAt");
32|			if (typeof baseline.headSha === "string" && baseline.headSha.trim()) {
33|				shas.headSha = baseline.headSha;
34|			}
35|			if (typeof baseline.baseSha === "string" && baseline.baseSha.trim()) {
36|				shas.baseSha = baseline.baseSha;
37|			}
38|		}
39|		if (typeof task?.mergeAttemptId === "string" && task.mergeAttemptId.trim()) {
40|			markers.push("mergeAttemptId");
41|		}
42|	} catch {
43|		// Marker reads are best-effort.
44|	}
45|	return { markers, shas, verdict };
46|}

